<section class="panel"><div class="panel-head"><div><h2>پرداخت‌های نیازمند تصمیم شما</h2><p>موارد مبهم هیچ‌وقت خودکار تأیید نمی‌شوند.</p></div></div><div class="table-wrap"><table><thead><tr><th>پرداخت</th><th>مبلغ گزارش‌شده</th><th>وضعیت پرداخت</th><th>وضعیت بررسی</th><th>تاریخ</th><th></th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="6"><div class="empty">هیچ پرداختی نیازمند بررسی نیست.</div></td></tr><?php else:foreach($rows as$row):?><tr><td><code><?= \CardPay\Core\View::e($row['public_id']) ?></code></td><td><?= $row['reported_amount']?number_format((int)$row['reported_amount']).' ریال':'—' ?></td><td><span class="badge violet"><?= \CardPay\Core\View::e($row['payment_status']) ?></span></td><td><span class="badge <?= $row['status']==='approved'?'success':($row['status']==='pending'?'warning':'neutral') ?>"><?= \CardPay\Core\View::e($row['status']) ?></span></td><td><?= \CardPay\Core\View::e(\CardPay\Core\View::localDate($row['created_at'],(string)($settings['timezone']??'Asia/Tehran'))) ?></td><td><a href="<?= \CardPay\Core\View::e(\CardPay\Core\Url::to('/admin/reviews/'.$row['id'])) ?>">بررسی</a></td></tr><?php endforeach;endif;?></tbody></table></div></section>
